const campaign = $('Check Campaign Status').first().json;
const adset = $('Check Ad Set Budget').first().json;
const account = $('Check Payment Method').first().json;

const campaign_ok = campaign.status === 'ACTIVE' && campaign.effective_status === 'ACTIVE';
const budget_ok = (adset.budget_remaining && parseFloat(adset.budget_remaining) > 0) || 
                  (adset.daily_budget && parseFloat(adset.daily_budget) > 0);
const account_ok = account.account_status === 1;
const all_clear = campaign_ok && budget_ok && account_ok;

let status_summary = 'Pre-Flight Check Results:\n\n';
status_summary += '✓ Campaign Status: ' + (campaign_ok ? 'PASSED - Campaign is ACTIVE' : 'FAILED - Campaign is ' + campaign.effective_status) + '\n';
status_summary += '✓ Budget Check: ' + (budget_ok ? 'PASSED - Budget available' : 'FAILED - No budget remaining') + '\n';
status_summary += '✓ Account Status: ' + (account_ok ? 'PASSED - Account active' : 'FAILED - Account status: ' + account.account_status) + '\n';

let action_needed = '';
if (!all_clear) {
  action_needed = 'Action needed in Meta Ads Manager:\n\n';
  if (!campaign_ok) {
    action_needed += '• Campaign is ' + campaign.effective_status + ' - Go to Campaigns tab and set status to ACTIVE\n';
  }
  if (!budget_ok) {
    action_needed += '• No budget remaining - Go to Ad Sets tab and increase daily_budget or add lifetime_budget\n';
  }
  if (!account_ok) {
    action_needed += '• Account status is ' + account.account_status + ' (not active) - Check payment method in Billing settings';
    if (account.disable_reason) {
      action_needed += ' (Reason: ' + account.disable_reason + ')';
    }
    action_needed += '\n';
  }
}

return [{
  json: {
    campaign_ok,
    budget_ok,
    account_ok,
    all_clear,
    status_summary,
    action_needed,
    campaign_data: campaign,
    adset_data: adset,
    account_data: account
  }
}];

const response = $('Check Ad Delivery Status').first().json;
const ads = response.data || [];

const problematic_ads = [];

for (const ad of ads) {
  const is_ok = ad.effective_status === 'ACTIVE' || ad.effective_status === 'IN_REVIEW';

  if (!is_ok) {
    problematic_ads.push({
      id: ad.id,
      name: ad.name,
      effective_status: ad.effective_status,
      delivery_info: ad.delivery_info || {},
      reason: ad.effective_status
    });
  }
}

const has_delivery_issues = problematic_ads.length > 0;

let issue_summary = '';
if (has_delivery_issues) {
  issue_summary = 'Delivery Issues Found:\n\n';
  for (const ad of problematic_ads) {
    issue_summary += 'Ad: ' + ad.name + ' (ID: ' + ad.id + ')\n';
    issue_summary += 'Status: ' + ad.effective_status + '\n';

    let explanation = '';
    switch (ad.effective_status) {
      case 'PAUSED':
        explanation = 'The ad is paused. Go to Ads Manager and set it to Active.';
        break;
      case 'DISAPPROVED':
        explanation = 'The ad was disapproved by Meta. Review the ad content and policy violations in Ads Manager.';
        break;
      case 'PENDING_REVIEW':
        explanation = 'The ad is still pending review. This is normal for new ads, check again in a few hours.';
        break;
      case 'CAMPAIGN_PAUSED':
        explanation = 'The parent campaign is paused. Go to Campaigns tab and activate it.';
        break;
      case 'ADSET_PAUSED':
        explanation = 'The parent ad set is paused. Go to Ad Sets tab and activate it.';
        break;
      default:
        explanation = 'Check Meta Ads Manager for details on status: ' + ad.effective_status;
    }

    issue_summary += 'Fix: ' + explanation + '\n\n';
  }
}

return [{
  json: {
    has_delivery_issues,
    problematic_ads,
    issue_summary,
    total_ads: ads.length,
    ads_ok: ads.length - problematic_ads.length
  }
}];
